DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `tenancy_id` bigint unsigned NOT NULL,
  `raw_message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `parsed_amount` decimal(12,2) DEFAULT NULL,
  `parsed_reference_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parsed_payment_method` enum('mpesa','bank','cash') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parsed_payment_datetime` timestamp NULL DEFAULT NULL,
  `parsed_payer_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parsed_paid_to` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parsed_payment_month` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remaining_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` enum('pending','verified','rejected','allocated','partial') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `verification_notes` text COLLATE utf8mb4_unicode_ci,
  `verified_by` bigint unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `transactions_user_id_foreign` (`user_id`),
  KEY `transactions_tenancy_id_foreign` (`tenancy_id`),
  KEY `transactions_verified_by_foreign` (`verified_by`),
  KEY `idx_transactions_status_tenancy` (`status`,`tenancy_id`),
  KEY `idx_transactions_reference_number` (`parsed_reference_number`),
  KEY `idx_transactions_created_at` (`created_at`),
  CONSTRAINT `transactions_tenancy_id_foreign` FOREIGN KEY (`tenancy_id`) REFERENCES `tenancies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `transactions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `transactions_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

